<span class="line"><span style="color:#E06C75;">redis</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">call</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;sadd&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">KEYS</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">] .. </span><span style="color:#98C379;">&#39;:processed&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">ARGV</span><span style="color:#ABB2BF;">[</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">])</span></span>
